const original = 'HTTPS://EXAMPLE.COM:443/Path/To/../To/Index/?b=2&a=1#fragment';
const normalized = normalizeUrl(original);
console.log(normalized); // 'https://example.com/Path/To/Index?a=1&b=2#fragment'

